// Normalized square coordinates preserve the output's aspect ratio at every size.
const limit=(n,a,b)=>Math.max(a,Math.min(b,Number.isFinite(+n)?+n:a));
export function normalizeRegionZoom(e){const size=limit(e.zoomSize??.4,.1,1),d=limit(e.duration??3,1/60,86400),zoomIn=limit(e.zoomIn??.2,0,d),zoomOut=limit(e.zoomOut??.3,0,d-zoomIn);return{...e,zoomSize:size,zoomX:limit(e.zoomX??.5,size/2,1-size/2),zoomY:limit(e.zoomY??.5,size/2,1-size/2),zoomIn,zoomOut,zoomTexts:e.zoomTexts!==false,zoomReturn:e.zoomReturn!==false,returnAt:limit(e.returnAt??Math.max(zoomIn,d-zoomOut),zoomIn,d-zoomOut)}}
export function regionZoomPose(effect,t){const e=normalizeRegionZoom(effect),local=t-e.start;if(local<0||local>=e.duration)return{scale:1,x:0,y:0};const smooth=u=>{u=limit(u,0,1);return u*u*(3-2*u)},enter=e.zoomIn?smooth(local/e.zoomIn):1,leave=e.zoomReturn&&local>=e.returnAt?(e.zoomOut?smooth((local-e.returnAt)/e.zoomOut):1):0,p=enter*(1-leave),scale=1+(1/e.zoomSize-1)*p;return{scale,x:(.5-e.zoomX)*(scale-1)/(1-e.zoomSize||1),y:(.5-e.zoomY)*(scale-1)/(1-e.zoomSize||1)}}
export function regionZoomTransform(effects,t){let scale=1,x=0,y=0;for(const e of effects){if(e.type!=='region-zoom')continue;const p=regionZoomPose(e,t);x=x*p.scale+p.x;y=y*p.scale+p.y;scale*=p.scale}return{scale,x,y}}
export function drawRegionZoom(ctx,source,scratch,effects,t,w,h){const p=regionZoomTransform(effects,t);if(p.scale===1)return;if(scratch.width!==w)scratch.width=w;if(scratch.height!==h)scratch.height=h;const copy=scratch.getContext('2d',{alpha:true});copy.clearRect?.(0,0,w,h);copy.drawImage(source,0,0,w,h);ctx.save();ctx.clearRect?.(0,0,w,h);ctx.globalAlpha=1;ctx.setTransform(p.scale,0,0,p.scale,w*(.5-.5*p.scale+p.x),h*(.5-.5*p.scale+p.y));ctx.drawImage(scratch,0,0,w,h);ctx.restore()}
